import{_ as e,o,c as t,a4 as n}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"分治","description":"","frontmatter":{},"headers":[],"relativePath":"dsa/algorithms/divide-conquer.md","filePath":"dsa/algorithms/divide-conquer.md","lastUpdated":1788475713000}'),s={name:"dsa/algorithms/divide-conquer.md"};function r(i,a,l,d,p,h){return o(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="分治" tabindex="-1">分治 <a class="header-anchor" href="#分治" aria-label="Permalink to &quot;分治&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>分治不是&quot;递归&quot; - 是&quot;<strong>先分解、再合并解</strong>&quot;的程序结构. 它刻意要求<strong>合并(merge)开销可控</strong>, 否则甚至比分而治之之前还不划算. 很多工程上人称&quot;分治&quot;的代码其实只是&quot;递归调用&quot;, 实质不是分治 (如mers 是&quot;分 + 合并行将&quot;), 看清楚&quot;merge 在哪儿&quot;就看清结构.</p><h2 id="模板" tabindex="-1">模板 <a class="header-anchor" href="#模板" aria-label="Permalink to &quot;模板&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>solve(P):</span></span>
<span class="line"><span>  if base case: return answer</span></span>
<span class="line"><span>  分 P = P1 ∪ P2</span></span>
<span class="line"><span>  A1 = solve(P1), A2 = solve(P2)</span></span>
<span class="line"><span>  return combine(A1, A2)</span></span></code></pre></div><p>经典案例: 归并排序、快速排序 (partition 是 pivot 排序)、Karatsuba 大整数乘法、最近点对 / 平面最近距离、二分搜索 (信息修改)、线段树 / 主席树基础.</p><h2 id="复杂度主定理回顾" tabindex="-1">复杂度主定理回顾 <a class="header-anchor" href="#复杂度主定理回顾" aria-label="Permalink to &quot;复杂度主定理回顾&quot;">​</a></h2><p><code>T(n) = a·T(n/b) + f(n)</code>, 结论见 <a href="./complexity/notation">复杂度分析</a>.</p><h2 id="经典-最近点对-平面" tabindex="-1">经典: 最近点对 (平面) <a class="header-anchor" href="#经典-最近点对-平面" aria-label="Permalink to &quot;经典: 最近点对 (平面)&quot;">​</a></h2><p>O(n log n):</p><ol><li>按 x 排序, 递归左侧和右侧;</li><li>合并时只考虑<strong>横跨分界线 ± δ 的点</strong> (δ = 左右解最小值), 按 y 排后需检查每点附近 6 个点.</li></ol><h2 id="经典-求逆序对" tabindex="-1">经典: 求逆序对 <a class="header-anchor" href="#经典-求逆序对" aria-label="Permalink to &quot;经典: 求逆序对&quot;">​</a></h2><p>归并排序的副产物 O(n log n): 归并过程中&quot;左半还剩 m 个值时, 从右半取的数所对应的逆序数加 m&quot;.</p><h2 id="工程多核化" tabindex="-1">工程多核化 <a class="header-anchor" href="#工程多核化" aria-label="Permalink to &quot;工程多核化&quot;">​</a></h2><p>分治天然适合 fork-join 工作窃取. 但分到原子 (n ≤ 1024) 就停下, 否则 fork 开销 &gt; 收益.</p><p>硬件视角: 分治的递归树形结构很难 GPU/FPGA 并行化, 但<strong>在分完之后</strong>的所有 leaf 任务可以 SIMD - 这就是分治在 NPU 编译器里的用法.</p><h2 id="易错" tabindex="-1">易错 <a class="header-anchor" href="#易错" aria-label="Permalink to &quot;易错&quot;">​</a></h2><ol><li><strong>merge 非 in-place</strong>: 归并排序需要 O(n) 辅助空间, 原地归并虽存在但常数大、专利多.</li><li><strong>base case 边界</strong>: n=1 / 0 都写好.</li><li><strong>并发分治</strong>: fork-join 框架天然适合分治, 但要测&quot;分到多大才 fork&quot;, 否则细粒度 fork 开销 &gt; 收益.</li></ol>`,18)])])}const q=e(s,[["render",r]]);export{u as __pageData,q as default};
